import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  AGENT_API_CARDS,
  AGENT_CONTEXT_MAX_BYTES,
  AGENT_GENERATOR_RECIPES,
  AGENT_PROTOCOL_VERSION,
  AGENT_PROTOCOL_STABILITY,
  AGENT_TASKS
} from "../packages/cli/dist/cli/protocol/catalog.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const checkOnly = process.argv.includes("--check");
const lines = [
  "# Agent Codegen Protocol",
  "",
  "<!-- Generated by scripts/generate-agent-protocol-docs.mjs. Do not edit by hand. -->",
  "",
  "> Online automation guide: [tavojs.dev/docs/cli/automation](https://tavojs.dev/docs/cli/automation)",
  "",
  `Tavo machine protocol v${AGENT_PROTOCOL_VERSION} is the ${AGENT_PROTOCOL_STABILITY} canonical CLI + JSON contract for autonomous code generation. Compact context is limited to ${AGENT_CONTEXT_MAX_BYTES} bytes; request full or targeted detail only when needed.`,
  "",
  "## Agent Loop",
  "",
  "```bash",
  "tavo agent-context --json --task modify-route --target /account",
  "tavo inspect route /account --json",
  "tavo change --from-json change.json --dry-run",
  "tavo change --from-json change.json > receipt.json",
  "tavo verify --receipt receipt.json --smoke --json",
  "tavo build",
  "```",
  "",
  "Every JSON response uses the protocol envelope: `schemaVersion`, `command`, `ok`, project fingerprint, `data`, diagnostics, next actions, and output metrics.",
  "",
  "## Tasks",
  "",
  ...AGENT_TASKS.map((task) => `- \`${task}\``),
  "",
  "## Canonical APIs",
  "",
  ...AGENT_API_CARDS.flatMap((card) => [
    `### ${card.id}`,
    "",
    `- Import: \`${card.import}\``,
    `- Signature: \`${card.signature}\``,
    `- Use when: ${card.useWhen}`,
    `- Avoid: ${card.avoid}`,
    ""
  ]),
  "## Structured Recipes",
  "",
  ...AGENT_GENERATOR_RECIPES.map((recipe) => `- **${recipe.id}:** \`${recipe.command}\`; verify with \`${recipe.verify}\`.`),
  "",
  "## Transaction Safety",
  "",
  "Change plans use schema version 1 and apply atomically. Existing-file replacements, fixes, and deletions require the exact SHA-256 returned by `tavo inspect`; fixes that create a missing file use `expectedMissing: true`. A stale precondition rejects the entire plan before writes. Generated and build directories cannot be change targets.",
  "",
  "Schemas ship under `tavo/schemas`: protocol, context, diagnostics, change plans, change receipts, and evaluation results.",
  "",
  "## Rules",
  "",
  "- Pages are functional modules under `src/pages`; use `defineRoutePage` only for explicit route-aware typing.",
  "- Interactive UI uses `createTavo`; do not invent React hooks.",
  "- Shared state uses `defineGlobalStore` and must not hold per-request secrets on the server.",
  "- Keep browser APIs out of loaders and server module initialization.",
  "- Never edit `.tavo/generated` or `.tavo/build`.",
  "- Finish with a production build after targeted verification passes.",
  ""
];

const outputFile = path.join(root, "docs", "agent-codegen.md");
const output = lines.join("\n");
if (checkOnly) {
  const current = await fs.readFile(outputFile, "utf8");
  if (current !== output) {
    throw new Error("docs/agent-codegen.md is stale. Run npm run docs:agent.");
  }
  console.log(`Verified docs/agent-codegen.md from protocol v${AGENT_PROTOCOL_VERSION}.`);
} else {
  await fs.writeFile(outputFile, output, "utf8");
  console.log(`Generated docs/agent-codegen.md from protocol v${AGENT_PROTOCOL_VERSION}.`);
}
